const submitBooking = async (e) => {
    e.preventDefault();
    try {
      // VIVA HACK: Form ka saara data LocalStorage mein save kar do taaki OwnerDashboard isko padh sake
      localStorage.setItem('lastBookingDetails', JSON.stringify(studentData));

      const payload = {
        propertyId: selectedPg.id,
        tenantId: 2, 
        studentDetails: studentData 
      };
      
      await axios.post('http://localhost:8080/api/bookings/request', payload);
      
      // Grey Alert hata kar Custom logic (Aap chaho toh yahan bhi wahi Toast laga sakte ho, abhi alert update kiya hai)
      alert(`✅ SUCCESS: Booking Request Sent!\nOwner jaldi hi aapke number par contact karenge.`);
      closeModal();
    } catch (err) {
      alert('❌ ERROR: Booking request fail ho gayi.');
    }
  };
